activity.solution:
ids = input().split()
seen = set()
processed = duplicates = 0
for i in ids:
    if i in seen:
        duplicates += 1
    else:
        seen.add(i)
        processed += 1
print(f'processed={processed} duplicates={duplicates}')

ALPHA = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
n = int(input())
if n == 0:
    print('0')
else:
    s = ''
    while n > 0:
        n, r = divmod(n, 62)
        s = ALPHA[r] + s
    print(s)
